1	//! Wiring between one frontend and one scheduler, plus the engine bundle a
2	//! model line hands back from `launch`.
3	//!
4	//! Both ends of a scheduler are minted together by [`scheduler_pair`], so a
5	//! model crate cannot cross-wire or forget a line: the scheduler side arrives
6	//! as one [`SchedulerBackend`] value, the frontend side as one
7	//! [`SchedulerHandle`]. Channel choices per direction: the submit channel is
8	//! crossbeam (sync consumer on the scheduler thread; senders never block on
9	//! unbounded channels), the step stream is tokio (async consumer in the
10	//! protocol stack; the sync producer's send never blocks either), metrics are
11	//! a shared cell, with changes signaled on the step stream (see
12	//! [`super::StepOutputs`]).
13	//!
14	//! How many schedulers an engine runs and what each one means (DP replicas,
15	//! anything else) is the model line's decision; the contract carries the
16	//! collection and attaches no rank semantics to it. Placement across
17	//! schedulers is frontend policy.
18	
19	use std::sync::Arc;
20	use std::sync::Mutex;
21	use std::sync::atomic::AtomicBool;
22	use std::sync::atomic::AtomicU64;
23	use std::sync::atomic::Ordering;
24	use std::time::Instant;
25	
26	use tokio_util::sync::CancellationToken;
27	use tokio_util::sync::DropGuard;
28	use tokio_util::sync::WaitForCancellationFuture;
29	
30	use super::control::LoraClient;
31	use super::kv::KvCapacity;
32	use super::ledger::RequestLedger;
33	use super::metrics::SchedulerMetrics;
34	use super::request_lifecycle::RequestControl;
35	use super::request_lifecycle::RequestEnvelope;
36	use super::request_lifecycle::StepReceiver;
37	use super::step::Request;
38	use super::step::RequestId;
39	
40	/// Everything the scheduler thread consumes and produces. The driver
41	/// ([`super::drive`]) destructures this; model code only ever sees the
42	/// ledger, through the `step` argument.
43	pub struct SchedulerBackend {
44	    pub(crate) submissions: crossbeam_channel::Receiver<RequestEnvelope>,
45	    pub(crate) ledger: RequestLedger,
46	    pub(crate) metrics: MetricsPublisher,
47	    /// Resolves [`SchedulerHandle::exited`] when dropped.
48	    pub(crate) exit_guard: DropGuard,
49	}
50	
51	/// Sole writer of a scheduler's metrics cell; the driver publishes once per
52	/// iteration from [`super::Scheduler::metrics`].
53	///
54	/// A `Mutex` (not per-field atomics) so a reader never sees fields torn
55	/// across two steps; both sides touch it uncontended for nanoseconds.
56	pub struct MetricsPublisher(Arc<Mutex<SchedulerMetrics>>);
57	
58	impl MetricsPublisher {
59	    pub(crate) fn publish(&self, snapshot: &SchedulerMetrics) -> bool {
60	        let mut current = self.0.lock().expect("metrics cell poisoned");
61	        let changed = *current != *snapshot;
62	        *current = *snapshot;
63	        changed
64	    }
65	}
66	
67	/// The frontend's end of one running scheduler.
68	pub struct SchedulerHandle {
69	    submit_tx: crossbeam_channel::Sender<RequestEnvelope>,
70	    steps: Option<StepReceiver>,
71	    metrics: Arc<Mutex<SchedulerMetrics>>,
72	    next_id: AtomicU64,
73	    /// Kept so requests minted after the scheduler thread exits still get
74	    /// their drop-bomb terminal delivered (the envelope needs a live sender).
75	    step_tx: super::request_lifecycle::StepSender,
76	    exited: CancellationToken,
77	}
78	
79	impl SchedulerHandle {
80	    /// Mint identity, queue timestamp, and abort flag, then hand the request
81	    /// to the scheduler. Never fails: if the scheduler is gone, the
82	    /// [`RequestEnvelope`]'s drop bomb answers the request with a
83	    /// `Failed` terminal on the step stream, which the caller observes like
84	    /// any other terminal.
85	    pub fn submit(&self, request: Request) -> RequestControl {
86	        let id = RequestId::new(self.next_id.fetch_add(1, Ordering::Relaxed));
87	        let abort = Arc::new(AtomicBool::new(false));
88	        let control = RequestControl::new(id, Arc::clone(&abort));
89	        let envelope =
90	            RequestEnvelope::new(id, abort, self.step_tx.clone(), request, Instant::now());
91	        if let Err(returned) = self.submit_tx.send(envelope) {
92	            drop(returned.into_inner());
93	        }
94	        control
95	    }
96	
97	    /// The step stream, handed out once (there is one stream and one
98	    /// consumer — the protocol stack's translation loop).
99	    pub fn take_steps(&mut self) -> Option<StepReceiver> {
100	        self.steps.take()
101	    }
102	
103	    /// The scheduler's most recent metrics snapshot. Read it when routing a
104	    /// request, receiving a step, or serving a scrape.
105	    pub fn metrics(&self) -> SchedulerMetrics {
106	        *self.metrics.lock().expect("metrics cell poisoned")
107	    }
108	
109	    /// Resolves once the driver has returned, after a fatal step or a drained
110	    /// shutdown, or its thread has unwound.
111	    pub fn exited(&self) -> WaitForCancellationFuture<'_> {
112	        self.exited.cancelled()
113	    }
114	}
115	
116	/// Mint both ends of one scheduler's wiring.
117	#[must_use]
118	pub fn scheduler_pair() -> (SchedulerHandle, SchedulerBackend) {
119	    let (submit_tx, submit_rx) = crossbeam_channel::unbounded();
120	    let (step_tx, step_rx) = tokio::sync::mpsc::unbounded_channel();
121	    let metrics = Arc::new(Mutex::new(SchedulerMetrics::default()));
122	    let exited = CancellationToken::new();
123	    (
124	        SchedulerHandle {
125	            submit_tx,
126	            steps: Some(step_rx),
127	            metrics: Arc::clone(&metrics),
128	            next_id: AtomicU64::new(0),
129	            step_tx: step_tx.clone(),
130	            exited: exited.clone(),
131	        },
132	        SchedulerBackend {
133	            submissions: submit_rx,
134	            ledger: RequestLedger::new(step_tx),
135	            metrics: MetricsPublisher(metrics),
136	            exit_guard: exited.drop_guard(),
137	        },
138	    )
139	}
140	
141	/// What `ModelLine::launch` returns for a step-driven engine — a handoff
142	/// package the protocol stack dissolves at wiring time. Required fields are
143	/// the onboarding checklist: an engine that reports no capacity or no
144	/// servable length says so explicitly with `None`, it cannot just forget.
145	pub struct Engine {
146	    /// The engine's running schedulers, one handle each. How many and what
147	    /// they mean is the model line's business.
148	    pub schedulers: Vec<LiveScheduler>,
149	    pub info: EngineInfo,
150	    /// LoRA adapter control, for engines that serve it. The `Option` is the
151	    /// capability — no separate flag exists to disagree with it.
152	    pub lora: Option<LoraClient>,
153	}
154	
155	pub struct LiveScheduler {
156	    pub handle: SchedulerHandle,
157	    /// The driver thread. Joined by the server at shutdown, after the handles
158	    /// (and with them the submit senders) are dropped.
159	    pub join: std::thread::JoinHandle<()>,
160	}
161	
162	/// What `ModelLine::launch` returns during the contract migration: either a
163	/// legacy per-token engine or a step-driven one. Deleted (in favor of
164	/// [`Engine`] alone) once every model line is migrated.
165	pub enum LaunchedEngine {
166	    Handle(super::handle::EngineHandle),
167	    Stepped(Engine),
168	}
169	
170	impl From<super::handle::EngineHandle> for LaunchedEngine {
171	    fn from(handle: super::handle::EngineHandle) -> Self {
172	        Self::Handle(handle)
173	    }
174	}
175	
176	impl From<Engine> for LaunchedEngine {
177	    fn from(engine: Engine) -> Self {
178	        Self::Stepped(engine)
179	    }
180	}
181	
182	#[derive(Clone, Copy, Debug)]
183	pub struct EngineInfo {
184	    /// KV pool capacity, or an explicit `None` for engines that do not report
185	    /// one (the frontend then skips batch-fit checks).
186	    pub kv_capacity: Option<KvCapacity>,
187	    /// Longest servable request in tokens, or an explicit `None` to leave the
188	    /// protocol stack's max-length validation at the model context window.
189	    pub servable_len: Option<u32>,
190	}
191

