1	//! What the scheduler republishes about itself: [`SchedulerMetrics`], the
2	//! per-iteration snapshot of occupancy gauges plus whatever richer counters a
3	//! model line serves (today: cumulative speculative-decode acceptance, when a
4	//! draft model is loaded, and cumulative prefix-cache lookups, when the engine
5	//! has a prefix cache).
6	
7	use std::error::Error;
8	use std::fmt;
9	
10	/// The metrics snapshot a scheduler republishes after every step.
11	///
12	/// `kv_used_blocks` is the load signal an out-of-band consumer (e.g. a Dynamo
13	/// KV router) scores against; `kv_total_blocks` is the engine's whole-pool
14	/// capacity (the same number advertised as the servable ceiling), so the
15	/// consumer can derive fractional usage without a second query. Readers only
16	/// ever see the latest snapshot — stepped engines publish into a shared cell
17	/// ([`super::MetricsPublisher`]), legacy engines over a `watch` channel — so
18	/// counters carried here must be cumulative totals, not per-step deltas (see
19	/// [`SpecDecodeCounters`]).
20	#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
21	pub struct SchedulerMetrics {
22	    pub kv_used_blocks: u64,
23	    pub kv_total_blocks: u64,
24	    /// Requests currently occupying a decode/prefill slot.
25	    pub num_running_reqs: u64,
26	    /// Requests admitted but not yet running (KV pressure, prefetch wait).
27	    pub num_waiting_reqs: u64,
28	    /// Cumulative spec-decode counters, or `None` when no draft model is loaded.
29	    pub spec_decode: Option<SpecDecodeCounters>,
30	    /// Cumulative prefix-cache counters, or `None` when the engine has no
31	    /// prefix cache.
32	    pub prefix_cache: Option<PrefixCacheCounters>,
33	}
34	
35	/// Cumulative prefix-cache counters in prompt tokens, monotone since the
36	/// engine started (totals for the same reason as [`SpecDecodeCounters`]).
37	/// `host_hits + external_unspecified_hits` never exceeds `hits`; every other
38	/// hit is reported as a device hit.
39	#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
40	pub struct PrefixCacheCounters {
41	    /// Prompt tokens looked up in the prefix cache.
42	    pub queries: u64,
43	    /// Prompt tokens served from the prefix cache, from any tier.
44	    pub hits: u64,
45	    /// Prompt tokens looked up in the connector's tiers (host memory and any
46	    /// deeper tier behind it); zero without a connector. Queries carry no
47	    /// source: the frontend splits only hits by tier.
48	    pub host_queries: u64,
49	    /// Of `hits`, tokens the engine knows were restored from host memory.
50	    pub host_hits: u64,
51	    /// Of `hits`, tokens restored through the connector from a tier the
52	    /// engine cannot attribute. A connector that answers from host memory,
53	    /// a P2P peer or SSD behind one call reports only a block count, so
54	    /// labeling those hits `host` would misattribute the peer and disk ones.
55	    pub external_unspecified_hits: u64,
56	}
57	
58	/// Upper bound on a drafter's `K`, fixing the width of
59	/// [`SpecDecodeCounters::num_accepted_tokens_per_pos`].
60	pub const MAX_SPEC_TOKENS: usize = 32;
61	
62	#[derive(Debug, Eq, PartialEq)]
63	pub struct SpecWidthUnsupported {
64	    pub num_spec_tokens: usize,
65	}
66	
67	impl fmt::Display for SpecWidthUnsupported {
68	    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
69	        write!(
70	            f,
71	            "draft checkpoint proposes K={} tokens per verify step, above the \
72	             MAX_SPEC_TOKENS={MAX_SPEC_TOKENS} the acceptance metrics support",
73	            self.num_spec_tokens
74	        )
75	    }
76	}
77	
78	impl Error for SpecWidthUnsupported {}
79	
80	/// Cumulative speculative-decode acceptance counters, monotone since the draft
81	/// model was loaded. Use totals rather than per-step deltas, because a
82	/// [`SchedulerMetrics`] reader only keeps the newest value: a reader that
83	/// misses a step would lose that delta for good, but it can still read totals
84	/// correctly.
85	#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
86	pub struct SpecDecodeCounters {
87	    /// The drafter's configured `K`, and the number of leading
88	    /// [`Self::num_accepted_tokens_per_pos`] entries that carry meaning.
89	    pub num_spec_tokens: u64,
90	    /// Draft proposals — one per request per verify step.
91	    pub num_drafts: u64,
92	    /// Draft tokens proposed for verification (pre-acceptance) in total.
93	    pub num_draft_tokens: u64,
94	    /// Draft tokens accepted in total, excluding the bonus token.
95	    pub num_accepted_tokens: u64,
96	    /// `[i]` is how often the `i`-th draft position was accepted. Only
97	    /// `[..num_spec_tokens]` is meaningful; the tail stays zero.
98	    pub num_accepted_tokens_per_pos: [u64; MAX_SPEC_TOKENS],
99	}
100	
101	impl SpecDecodeCounters {
102	    pub fn new(num_spec_tokens: usize) -> Result<Self, SpecWidthUnsupported> {
103	        if num_spec_tokens > MAX_SPEC_TOKENS {
104	            return Err(SpecWidthUnsupported { num_spec_tokens });
105	        }
106	        Ok(Self {
107	            num_spec_tokens: num_spec_tokens as u64,
108	            ..Self::default()
109	        })
110	    }
111	
112	    pub fn observe_draft(&mut self, num_draft_tokens: usize, num_accepted: usize) {
113	        self.num_drafts += 1;
114	        self.num_draft_tokens += num_draft_tokens as u64;
115	        self.num_accepted_tokens += num_accepted as u64;
116	        let tallied = num_accepted.min(self.num_spec_tokens as usize);
117	        for slot in self.num_accepted_tokens_per_pos.iter_mut().take(tallied) {
118	            *slot += 1;
119	        }
120	    }
121	}
122	
123	#[cfg(test)]
124	mod tests {
125	    use super::*;
126	
127	    #[test]
128	    fn observe_draft_tallies_a_prefix_per_position() {
129	        let mut counters = SpecDecodeCounters::new(3).expect("K within bounds");
130	        // Two drafts proposed, both accepted; then three proposed, one accepted.
131	        counters.observe_draft(2, 2);
132	        counters.observe_draft(3, 1);
133	        assert_eq!(counters.num_drafts, 2);
134	        assert_eq!(counters.num_draft_tokens, 5);
135	        assert_eq!(counters.num_accepted_tokens, 3);
136	        // Acceptance is prefix-shaped: `n` accepted tokens credit positions
137	        // `0..n`, so a per-position histogram never rises.
138	        assert_eq!(&counters.num_accepted_tokens_per_pos[..3], &[2, 1, 0]);
139	    }
140	
141	    #[test]
142	    fn oversized_k_is_rejected_not_truncated() {
143	        assert!(SpecDecodeCounters::new(MAX_SPEC_TOKENS).is_ok());
144	        assert_eq!(
145	            SpecDecodeCounters::new(MAX_SPEC_TOKENS + 1),
146	            Err(SpecWidthUnsupported {
147	                num_spec_tokens: MAX_SPEC_TOKENS + 1
148	            })
149	        );
150	    }
151	}
