40	/// Everything the scheduler thread consumes and produces. The driver
41	/// ([`super::drive`]) destructures this; model code only ever sees the
42	/// ledger, through the `step` argument.
43	pub struct SchedulerBackend {
44	    pub(crate) submissions: crossbeam_channel::Receiver<RequestEnvelope>,
45	    pub(crate) ledger: RequestLedger,
46	    pub(crate) metrics: MetricsPublisher,
47	    /// Resolves [`SchedulerHandle::exited`] when dropped.
48	    pub(crate) exit_guard: DropGuard,
49	}
50	
51	/// Sole writer of a scheduler's metrics cell; the driver publishes once per
52	/// iteration from [`super::Scheduler::metrics`].
53	///
54	/// A `Mutex` (not per-field atomics) so a reader never sees fields torn
55	/// across two steps; both sides touch it uncontended for nanoseconds.
56	pub struct MetricsPublisher(Arc<Mutex<SchedulerMetrics>>);
57	
58	impl MetricsPublisher {
59	    pub(crate) fn publish(&self, snapshot: &SchedulerMetrics) -> bool {
60	        let mut current = self.0.lock().expect("metrics cell poisoned");
61	        let changed = *current != *snapshot;
62	        *current = *snapshot;
63	        changed
64	    }
65	}
66	
67	/// The frontend's end of one running scheduler.
68	pub struct SchedulerHandle {
69	    submit_tx: crossbeam_channel::Sender<RequestEnvelope>,
70	    steps: Option<StepReceiver>,
71	    metrics: Arc<Mutex<SchedulerMetrics>>,
72	    next_id: AtomicU64,
73	    /// Kept so requests minted after the scheduler thread exits still get
74	    /// their drop-bomb terminal delivered (the envelope needs a live sender).
75	    step_tx: super::request_lifecycle::StepSender,
76	    exited: CancellationToken,
77	}
