79	impl SchedulerHandle {
80	    /// Mint identity, queue timestamp, and abort flag, then hand the request
81	    /// to the scheduler. Never fails: if the scheduler is gone, the
82	    /// [`RequestEnvelope`]'s drop bomb answers the request with a
83	    /// `Failed` terminal on the step stream, which the caller observes like
84	    /// any other terminal.
85	    pub fn submit(&self, request: Request) -> RequestControl {
86	        let id = RequestId::new(self.next_id.fetch_add(1, Ordering::Relaxed));
87	        let abort = Arc::new(AtomicBool::new(false));
88	        let control = RequestControl::new(id, Arc::clone(&abort));
89	        let envelope =
90	            RequestEnvelope::new(id, abort, self.step_tx.clone(), request, Instant::now());
91	        if let Err(returned) = self.submit_tx.send(envelope) {
92	            drop(returned.into_inner());
93	        }
94	        control
95	    }
96	
97	    /// The step stream, handed out once (there is one stream and one
98	    /// consumer — the protocol stack's translation loop).
99	    pub fn take_steps(&mut self) -> Option<StepReceiver> {
100	        self.steps.take()
101	    }
102	
103	    /// The scheduler's most recent metrics snapshot. Read it when routing a
104	    /// request, receiving a step, or serving a scrape.
105	    pub fn metrics(&self) -> SchedulerMetrics {
106	        *self.metrics.lock().expect("metrics cell poisoned")
107	    }
108	
109	    /// Resolves once the driver has returned, after a fatal step or a drained
110	    /// shutdown, or its thread has unwound.
111	    pub fn exited(&self) -> WaitForCancellationFuture<'_> {
112	        self.exited.cancelled()
113	    }
114	}
115	
116	/// Mint both ends of one scheduler's wiring.
117	#[must_use]
118	pub fn scheduler_pair() -> (SchedulerHandle, SchedulerBackend) {
119	    let (submit_tx, submit_rx) = crossbeam_channel::unbounded();
120	    let (step_tx, step_rx) = tokio::sync::mpsc::unbounded_channel();
121	    let metrics = Arc::new(Mutex::new(SchedulerMetrics::default()));
122	    let exited = CancellationToken::new();
123	    (
124	        SchedulerHandle {
125	            submit_tx,
126	            steps: Some(step_rx),
127	            metrics: Arc::clone(&metrics),
128	            next_id: AtomicU64::new(0),
129	            step_tx: step_tx.clone(),
130	            exited: exited.clone(),
131	        },
132	        SchedulerBackend {
133	            submissions: submit_rx,
134	            ledger: RequestLedger::new(step_tx),
135	            metrics: MetricsPublisher(metrics),
136	            exit_guard: exited.drop_guard(),
137	        },
138	    )
139	}
