141	/// What `ModelLine::launch` returns for a step-driven engine — a handoff
142	/// package the protocol stack dissolves at wiring time. Required fields are
143	/// the onboarding checklist: an engine that reports no capacity or no
144	/// servable length says so explicitly with `None`, it cannot just forget.
145	pub struct Engine {
146	    /// The engine's running schedulers, one handle each. How many and what
147	    /// they mean is the model line's business.
148	    pub schedulers: Vec<LiveScheduler>,
149	    pub info: EngineInfo,
150	    /// LoRA adapter control, for engines that serve it. The `Option` is the
151	    /// capability — no separate flag exists to disagree with it.
152	    pub lora: Option<LoraClient>,
153	}
154	
155	pub struct LiveScheduler {
156	    pub handle: SchedulerHandle,
157	    /// The driver thread. Joined by the server at shutdown, after the handles
158	    /// (and with them the submit senders) are dropped.
159	    pub join: std::thread::JoinHandle<()>,
160	}
161	
162	/// What `ModelLine::launch` returns during the contract migration: either a
163	/// legacy per-token engine or a step-driven one. Deleted (in favor of
164	/// [`Engine`] alone) once every model line is migrated.
165	pub enum LaunchedEngine {
166	    Handle(super::handle::EngineHandle),
167	    Stepped(Engine),
168	}
169	
170	impl From<super::handle::EngineHandle> for LaunchedEngine {
171	    fn from(handle: super::handle::EngineHandle) -> Self {
172	        Self::Handle(handle)
173	    }
174	}
175	
176	impl From<Engine> for LaunchedEngine {
177	    fn from(engine: Engine) -> Self {
178	        Self::Stepped(engine)
179	    }
180	}
181	
182	#[derive(Clone, Copy, Debug)]
183	pub struct EngineInfo {
184	    /// KV pool capacity, or an explicit `None` for engines that do not report
185	    /// one (the frontend then skips batch-fit checks).
186	    pub kv_capacity: Option<KvCapacity>,
187	    /// Longest servable request in tokens, or an explicit `None` to leave the
188	    /// protocol stack's max-length validation at the model context window.
189	    pub servable_len: Option<u32>,
190	}
