223	        &self,
224	        step: StepOutputs,
225	        anchor: &UnixAnchor,
226	        streams: &mut HashMap<RequestId, SteppedStream>,
227	        names: &mut HashMap<String, RequestId>,
228	        tracker: &mut StatsTracker,
229	        output_tx: &tokio::sync::mpsc::UnboundedSender<
230	            vllm_engine_core_client::protocol::output::EngineCoreOutputs,
231	        >,
232	    ) -> Result<()> {
233	        let mut outputs: Vec<EngineCoreOutput> = Vec::with_capacity(step.updates.len());
234	        let mut finished_requests: BTreeSet<String> = BTreeSet::new();
235	        for update in step.updates {
236	            // No stream entry means the request was aborted or already
237	            // finished; late updates (including retire-window drop bombs) are
238	            // dropped.
239	            let Some(state) = streams.get_mut(&update.id) else {
240	                continue;
241	            };
242	            let id = update.id;
243	            let (output, terminated) = reduce_update(state, update, anchor);
244	            if let Some(output) = output {
245	                outputs.push(output);
246	            }
247	            if terminated {
248	                // Dropping the state ends the root span, closing the trace.
249	                let state = streams.remove(&id).expect("terminated stream present");
250	                names.remove(&state.request_id);
251	                finished_requests.insert(state.request_id);
252	            }
253	        }
254	
255	        send_outputs(
256	            output_tx,
257	            RequestBatchOutputs {
258	                engine_index: self.engine_index,
259	                outputs,
260	                finished_requests: (!finished_requests.is_empty()).then_some(finished_requests),
261	                scheduler_stats: Some(Box::new(self.stats(tracker))),
262	                timestamp: now_secs_f64(),
263	                weight_version: None,
264	            }
265	            .into(),
266	        )
267	    }
